{"cards": [{"node_code": "N_76937bae402c978c", "definition": "研究汽车及其零部件在预定条件下、规定时间内完成规定功能的能力，涵盖故障率、平均无故障里程、寿命预测及可靠性评估模型。", "boundary": "本节点聚焦于“可靠性”的理论分析与统计评估。边界在于区分“可靠性理论”与“维修技术”（维修归汽车保养与修理）、“可靠性”与“安全性”（安全侧重事故后果，可靠侧重功能失效）。若内容涉及具体零部件的疲劳寿命计算，归本节点；若涉及整车碰撞安全，归汽车的安全性。", "includes": ["汽车故障模式与影响分析（FMEA）", "可靠性统计模型、寿命分布及加速寿命试验理论", "整车及关键系统的可靠性指标计算与评估方法"], "excludes": ["汽车故障诊断与维修工艺", "汽车碰撞安全与被动安全设计"], "sibling_distinctions": [{"other_code": "N_59013ac50d9aaa64", "rule": "可靠性关注“功能失效概率与寿命”，安全性关注“事故后果与乘员保护”。"}, {"other_code": "N_0115d7a840896978", "rule": "动力性关注“加速与爬坡能力”，可靠性关注“长期运行中的故障率”。"}], "cross_boundary_rule": "若内容涉及“基于可靠性数据的维修策略”，主挂载汽车可靠性；若涉及“具体维修操作”，主挂载汽车保养与修理。"}, {"node_code": "N_3aab23d0ae365d3a", "definition": "研究汽车在行驶过程中燃料消耗规律的理论学科，涵盖燃油消耗率、百公里油耗、能量转换效率及影响经济性的因素分析。", "boundary": "本节点聚焦于“燃料经济性”的理论计算与影响因素。边界在于区分“经济性理论”与“发动机结构”（结构归汽车结构部件）、“经济性”与“动力性”（动力侧重功率输出，经济侧重能耗效率）。若内容涉及混合动力能量管理策略的理论模型，归本节点；若涉及发动机燃烧室结构设计，归结构部件。", "includes": ["汽车燃油消耗率与百公里油耗的理论计算", "影响燃料经济性的因素（如车速、载荷、路况）分析", "新能源汽车能量效率与续航能力的理论评估"], "excludes": ["发动机具体结构设计与制造工艺", "汽车使用中的节油驾驶技巧"], "sibling_distinctions": [{"other_code": "N_0115d7a840896978", "rule": "动力性关注“做功能力与速度”，燃料经济性关注“能耗效率与成本”。"}, {"other_code": "N_d67b327312aeed46", "rule": "动力学关注“运动与受力”，燃料经济性关注“能量转换与消耗”。"}], "cross_boundary_rule": "若内容涉及“动力性与经济性的匹配优化”，主挂载汽车燃料经济性（若侧重能耗）或汽车动力性（若侧重性能），需视具体侧重点；通常能耗优化归本节点。"}, {"node_code": "N_59013ac50d9aaa64", "definition": "研究汽车在行驶及事故状态下保护乘员、行人及车辆自身安全的理论，涵盖主动安全、被动安全、碰撞力学及安全性能评价指标。", "boundary": "本节点聚焦于“安全性”的理论分析与事故预防/保护机制。边界在于区分“安全性”与“可靠性”（可靠侧重功能失效，安全侧重事故后果）、“安全性”与“操纵稳定性”（操纵侧重可控性，安全侧重事故后果）。若内容涉及碰撞吸能结构设计，归本节点；若涉及制动距离计算，归汽车制动性。", "includes": ["汽车碰撞安全理论与乘员保护机制", "主动安全系统（如ABS、ESP）的理论原理", "行人保护及车辆安全性能评价指标体系"], "excludes": ["汽车日常驾驶安全规范与交通法规", "汽车故障导致的非碰撞性失效（归可靠性）"], "sibling_distinctions": [{"other_code": "N_76937bae402c978c", "rule": "安全性关注“事故后果与保护”，可靠性关注“功能失效概率”。"}, {"other_code": "N_e2c6c5780e42807e", "rule": "操纵稳定性关注“车辆可控性”，安全性关注“事故状态下的保护”。"}], "cross_boundary_rule": "若内容涉及“制动失效导致的碰撞安全”，主挂载汽车的安全性；若涉及“制动系统本身的性能”，主挂载汽车制动性。"}]}
